{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Disopyramide, a close analogue with a similarly high basic pKa and comparable molecular weight/rotatable bonds, had absolute oral bioavailability of 73% versus i.v. in human subjects, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "DMD, the mono-N-dealkylated disopyramide metabolite, showed 50% absolute oral bioavailability in normal subjects, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Imidafenacin had absolute oral bioavailability of 57.8% (95% CI 54.1–61.4) in healthy subjects, supporting high oral bioavailability for this class of moderately lipophilic basic drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Bepotastine exhibited >80% oral bioavailability in humans, providing additional supportive evidence that high basic pKa does not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Terfenadine had <2% oral bioavailability in men, a contradictory low-F example, but its low F is mechanistically attributed to extensive first-pass metabolism and physicochemical properties not shared by the query analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The closest analogues with similar basic amine pKa and moderate physicochemical properties—disopyramide, DMD, imidafenacin, and bepotastine—consistently show absolute oral bioavailability ≥50%, well above the 20% threshold. The only low-F analogue, terfenadine, is mechanistically distinct due to extensive first-pass metabolism and poor solubility. Therefore, high oral bioavailability is predicted.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule itself.",
    "Exact structural identity of the query is not provided, limiting direct analogue matching.",
    "First-pass metabolism and transporter effects for the query are not directly assessed.",
    "Terfenadine's low-F mechanism is not directly transferable to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

